BRANCHES = ["rachel", "monica", "phoebe", "joey", "chandler", "ross"]
EP = "S04/E13"

def git(*args):
    return subprocess.run(["git", "-C", REPO] + list(args), capture_output=True, text=True).stdout

def parse(sha, branch):
    body = git("show", "-s", "--format=%B", sha)
    if "Friend-Message: 1" not in body:
        return None
    ct = int(git("show", "-s", "--format=%ct", sha).strip())
    lines = body.split("\n")
    speaker = episode = replyto = None
    corr = None
    i = 0
    while i < len(lines):
        line = lines[i]
        if line.startswith("Speaker: "):
            speaker = line[9:].strip()
        elif line.startswith("Episode: "):
            episode = line[9:].strip()
        elif line.startswith("Reply-To: "):
            replyto = line[10:].strip()
        elif line.startswith("Correction-Request: "):
            corr = line[19:].strip()
        elif line.strip() == "" and speaker and episode and replyto is not None and i > 0:
            break
        i += 1
    text = "\n".join(lines[i + 1:]).strip("\n")
    return dict(sha=sha, ct=ct, branch="friend/" + branch, speaker=speaker,
                episode=episode, reply_to=replyto, correction=corr, text=text)

entries = []
for b in BRANCHES:
    for sha in git("log", "--format=%H", "origin/friend/" + b).split():
        e = parse(sha, b)
        if e:
            entries.append(e)

recorded = set()
for f in glob.glob(os.path.join(MAIN, "S*", "E*.md")):
    for m in re.finditer(r"Source: friend/\w+ @ ([0-9a-f]{40})", open(f).read()):
        recorded.add(m.group(1))

mine = [e for e in entries if e["episode"] == EP and e["sha"] not in recorded]
mine.sort(key=lambda x: (x["ct"], x["sha"]))
print("to append:", len(mine))

def block(e):
    ts = datetime.fromtimestamp(e["ct"], timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
    return "**%s** (%s)\n\nSource: %s @ %s\n\n%s\n" % (e["speaker"], ts, e["branch"], e["sha"], e["text"])

path = os.path.join(MAIN, "S0" + EP[1:3], "E" + EP[4:].zfill(2) + ".md")
path = os.path.join(MAIN, "S04", "E13.md")
text = open(path).read()
add = "\n".join(block(e) for e in mine)
text = text.rstrip("\n") + "\n\n" + add
open(path, "w").write(text)
print("wrote", path, "appended", len(mine))
json.dump([e["sha"] for e in mine], open("/tmp/appended.json", "w"))
for e in mine:
    print(e["ct"], e["speaker"], e["sha"][:9], "CORR" if e["correction"] else "")
